using Microsoft.Extensions.AI;
using OpenAI;
using System.ClientModel;
using System.ComponentModel;
using System.Text.RegularExpressions;

// --- Configuration ---
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable.");
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// --- Tools ---
var notebook = new Notebook();
var webSearcher = new WebSearcher();

var tools = new AITool[]
{
    AIFunctionFactory.Create(webSearcher.SearchWeb),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

// --- Chat client with automatic function-calling loop ---
IChatClient client = new OpenAIClient(new ApiKeyCredential(openAiKey))
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// --- Interactive loop ---
Console.WriteLine("🔬 Research Agent");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");

while (true)
{
    Console.Write("\n> ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) ||
        topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, """
            You are a research agent. When given a topic:
            1. Use the SearchWeb tool 2-3 times with varied queries to gather information.
            2. Use AddNote to record key findings from each search.
            3. Use GetNotes to review everything you collected.
            4. Provide a comprehensive summary with cited sources.
            Be thorough but concise.
            """),
        new(ChatRole.User, $"Research the following topic: {topic}")
    };

    Console.WriteLine($"\n🔍 Researching: {topic}\n");

    var response = await client.GetResponseAsync(messages, new()
    {
        Tools = [.. tools],
    });

    Console.WriteLine("\n📋 Research Summary:");
    Console.WriteLine(new string('─', 60));
    Console.WriteLine(response.Text);
    Console.WriteLine(new string('─', 60));
}

// ---------------------------------------------------------------------------
// Tool: Web Search (DuckDuckGo Lite – no API key required)
// ---------------------------------------------------------------------------
public sealed class WebSearcher
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "text/html" }
        }
    };

    [Description("Searches the web for a query and returns result snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query")] string query)
    {
        Console.WriteLine($"  🌐 Searching: {query}");
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var html = await Http.GetStringAsync(
                $"https://lite.duckduckgo.com/lite/?q={encoded}");

            var results = ParseResults(html);
            return results.Length > 0
                ? string.Join("\n\n", results.Take(5))
                : "No results found.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static string[] ParseResults(string html)
    {
        var results = new List<string>();
        const string snippetTag = "<td class=\"result-snippet\">";
        const string linkTag = "<a rel=\"nofollow\" href=\"";

        var pos = 0;
        while ((pos = html.IndexOf(snippetTag, pos, StringComparison.Ordinal)) >= 0)
        {
            pos += snippetTag.Length;
            var end = html.IndexOf("</td>", pos, StringComparison.Ordinal);
            if (end < 0) break;

            var snippet = StripHtml(html[pos..end]).Trim();

            // Find the preceding link for source attribution
            var preceding = html[..pos];
            var linkPos = preceding.LastIndexOf(linkTag, StringComparison.Ordinal);
            var source = "";
            if (linkPos >= 0)
            {
                linkPos += linkTag.Length;
                var linkEnd = html.IndexOf('"', linkPos);
                if (linkEnd > linkPos)
                    source = $" [Source: {html[linkPos..linkEnd]}]";
            }

            if (!string.IsNullOrWhiteSpace(snippet))
                results.Add($"{snippet}{source}");
        }

        return [.. results];
    }

    private static string StripHtml(string html) =>
        Regex.Replace(html, "<[^>]+>", " ")
             .Replace("&amp;", "&")
             .Replace("&lt;", "<")
             .Replace("&gt;", ">")
             .Replace("&quot;", "\"")
             .Replace("&#x27;", "'");
}

// ---------------------------------------------------------------------------
// Tool: Notebook for recording research findings
// ---------------------------------------------------------------------------
public sealed class Notebook
{
    private readonly List<string> _notes = [];

    [Description("Saves a note to the research notebook.")]
    public string AddNote(
        [Description("The note text to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note #{_notes.Count} saved");
        return $"Note #{_notes.Count} saved.";
    }

    [Description("Returns all notes in the research notebook.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes recorded yet.";
        return string.Join("\n", _notes.Select((n, i) => $"[{i + 1}] {n}"));
    }

    public void Clear() => _notes.Clear();
}

